"""The results page's numbers, each one beside the dataset it was read over.

Every metric the site shows is read here, once, from the four harnesses Part 27
built.  This module is their only reader on the way to the page: the rows are
rendered to ``frontend/results-metrics.js`` and committed, so the page never
imports a fixture and ``app`` never grows the test edge D221 records.
"""

import json
import sys
from functools import lru_cache
from pathlib import Path
from typing import NamedTuple

from tests.fixtures import (
    document_corpus,
    evaluation,
    face_evaluation,
    latency_benchmark,
    morph_evaluation,
)

__all__ = [
    "checked",
    "DATASETS",
    "DESIGNED",
    "DRAWN_CORPUS",
    "METRIC_PATH",
    "MEASURED",
    "METRICS",
    "Metric",
    "MetricWithoutDataset",
    "NOT_MEASURED",
    "NO_NUMBER",
    "STUBBED",
    "metrics",
    "render",
    "write",
]

#: The header of the generated file, so its origin is on the page's own source.
HEADER = (
    "// Generated by backend/tests/fixtures/results_view.py -- do not edit.\n"
    "// Regenerate with: python -m tests.fixtures.results_view\n"
)

#: Where the generated file lives, read from here so one name holds it.
METRIC_PATH = (
    Path(__file__).resolve().parents[3] / "frontend" / "results-metrics.js"
)

#: A real model read the number over a dataset.
MEASURED = "measured"

#: Only stand-ins produced the number behind it.
STUBBED = "stub"

#: The number is the abstract's target and no dataset was read over it.
DESIGNED = "designed"

#: Nothing was read, so there is no number to show.
NOT_MEASURED = "not measured"

#: What a row with no reading shows in place of a number.
NO_NUMBER = "--"

#: The one dataset this repository can measure over, named once.
DRAWN_CORPUS = "drawn-corpus"


class MetricWithoutDataset(ValueError):
    """A metric shows a number and no dataset to say it was read over."""


class Dataset(NamedTuple):
    """One named body of data a number can be read over.

    ``detail`` is what a reader is owed about it: how it was drawn and what
    held it to be true.
    """

    id: str
    name: str
    detail: str


class Metric(NamedTuple):
    """One number the page shows, and everything that makes it readable.

    ``value`` is the number as shown, or :data:`NO_NUMBER` where nothing was
    read.  ``dataset`` names a :class:`Dataset`, and is empty only where
    ``source`` is :data:`DESIGNED` -- a target is the one row a page may show
    without a dataset behind it.
    """

    id: str
    label: str
    value: str
    source: str
    dataset: str
    detector: str
    note: str

    @property
    def shows_a_number(self):
        """Whether this row shows a number rather than :data:`NO_NUMBER`."""
        return self.value != NO_NUMBER

    @property
    def is_design_target(self):
        """Whether this row is the abstract's target rather than a reading."""
        return self.source == DESIGNED


DATASETS = (
    Dataset(
        DRAWN_CORPUS,
        "Synthetic document corpus",
        f"{len(document_corpus.DOCUMENT_TYPES)} document types x "
        f"{len(evaluation.DEFAULT_SEEDS)} seeds x one clean page and one page "
        "per tamper kind, held to document_manifest.py's ground truth. Drawn by "
        "tests/fixtures/document_corpus.py; no real identity data is in it.",
    ),
)


def checked(metric):
    """``metric``, refused where it breaks Gate 27's one rule.

    :raises MetricWithoutDataset: for a number with no dataset that is not a
        design target, and for a design target that claims a dataset.
    """
    if metric.is_design_target:
        if metric.dataset:
            raise MetricWithoutDataset(
                f"{metric.id} is a design target and must not name a dataset."
            )
        return metric
    if metric.shows_a_number and not metric.dataset:
        raise MetricWithoutDataset(
            f"{metric.id} shows {metric.value} and names no dataset, so the "
            "number would be shown with nothing behind it."
        )
    if not metric.shows_a_number and metric.source in (MEASURED, STUBBED):
        raise MetricWithoutDataset(
            f"{metric.id} is {metric.source} and shows no number, which is a "
            "reading with nothing in it."
        )
    return metric



def _source(value):
    """``MEASURED`` where ``value`` is a reading, else :data:`NOT_MEASURED`.

    A rate with no denominator is not a measured zero: nothing was counted, so
    the row says so rather than showing a share no detector achieved.
    """
    return MEASURED if value != NO_NUMBER else NOT_MEASURED


def _corpus_metrics():
    """The corpus harness's rates, each over :data:`DRAWN_CORPUS`."""
    report = evaluation.evaluate(_corpus())
    detector = "read_zone"
    rows = [
        (
            "field_accuracy",
            "Field extraction accuracy",
            str(report.fields),
            "MRZ fields read correctly, over every field the manifest holds.",
        ),
        (
            "tamper_catch_rate",
            "Tamper catch rate",
            str(report.caught),
            "Injections the detector named, over the injections drawn.",
        ),
        (
            "false_alert_rate",
            "False-alert rate",
            str(report.false_alerts),
            "Clean pages the detector alarmed on, over the clean pages.",
        ),
        (
            "region_overlap",
            "Region overlap (mean IoU)",
            _overlap(report.overlap),
            f"Mean IoU over the {report.overlap.count} caught injections, at "
            f"or above the {evaluation.OVERLAP_THRESHOLD} threshold.",
        ),
        (
            "localized_region",
            "Caught and pointed at the edit",
            _empty_rate(report.localized),
            "Counted over the caught injections, not over all of them.",
        ),
    ]
    rows += [
        (
            f"tamper_catch_{kind}",
            f"Tamper caught: {kind}",
            str(report.by_kind[kind]),
            "One kind's own rate, over the injections of that kind.",
        )
        for kind in sorted(report.by_kind)
    ]
    return [
        checked(
            Metric(row, label, value, _source(value), DRAWN_CORPUS, detector,
                   note)
        )
        for row, label, value, note in rows
    ]

def _overlap(mean):
    """``mean`` as three decimals, or :data:`NO_NUMBER` where nothing averaged."""
    return NO_NUMBER if mean.value is None else f"{mean.value:.3f}"

def _face_metrics():
    """The face harness's two rates, over no dataset: none is installed."""
    report = face_evaluation.evaluate()
    note = "; ".join(
        face_evaluation.REASONS[reason] for reason in report.reasons
    )
    metrics = [
        Metric("face_false_accept_rate", "Face false-accept rate (FAR)",
               _empty_rate(report.far), report.source, "", "insightface", note),
        Metric("face_false_reject_rate", "Face false-reject rate (FRR)",
               _empty_rate(report.frr), report.source, "", "insightface", note),
    ]
    metrics += [
        Metric(f"face_far_{group.dimension}_{group.label}",
               f"FAR: {group.dimension} {group.label}",
               _empty_rate(report.by_group[group].far), report.source, "",
               "insightface", note)
        for group in face_evaluation.DEMOGRAPHIC_GROUPS
    ]
    return [checked(metric) for metric in metrics]


def _empty_rate(rate):
    """``rate`` as shown, or :data:`NO_NUMBER` where nothing was counted."""
    return NO_NUMBER if rate.denominator == 0 else str(rate)


def _morph_metrics():
    """The morph and deepfake harness's two numbers, over no corpus."""
    report = morph_evaluation.evaluate()
    note = "; ".join(
        morph_evaluation.REASONS[reason] for reason in report.reasons
    )
    metrics = [
        Metric("morph_attacks_missed", "Morph and deepfake attacks missed",
               _empty_rate(report.overall.missed), report.source, "",
               report.overall.classifier, note),
        Metric("morph_genuine_flagged", "Genuine photographs wrongly flagged",
               _empty_rate(report.overall.flagged), report.source, "",
               report.overall.classifier, note),
    ]
    metrics += [
        Metric(f"morph_missed_{kind}", f"Attacks missed: {kind}",
               _empty_rate(report.by_kind[kind].missed), report.source, "",
               report.by_kind[kind].classifier, note)
        for kind in morph_evaluation.ATTACK_KINDS
    ]
    return [checked(metric) for metric in metrics]


def _latency_metrics():
    """The abstract's latency windows, which no dataset was read over."""
    return [
        checked(Metric(
            f"latency_{tier}", f"{tier.replace('_', ' ').title()} per document",
            target.label, DESIGNED, "", "none",
            "The abstract's design target. Nothing was measured for this tier "
            "on the machine that wrote this file; latency_benchmark.py holds "
            "the reading.",
        ))
        for tier, target in latency_benchmark.TARGETS.items()
    ]


@lru_cache(maxsize=1)
def _corpus():
    """The drawn corpus, drawn once per process rather than once per call."""
    return evaluation.corpus()


@lru_cache(maxsize=1)
def metrics():
    """Every metric the page shows, in the order it shows them.

    Cached because reading the corpus is the whole cost of this module, and
    every caller -- the page's file, the freshness test, the refusals -- wants
    the same rows.
    """
    return tuple(
        _corpus_metrics()
        + _face_metrics()
        + _morph_metrics()
        + _latency_metrics()
    )


def payload():
    """``metrics()`` and the datasets they name, as the page reads them."""
    return {
        "datasets": [dataset._asdict() for dataset in DATASETS],
        "metrics": [metric._asdict() for metric in metrics()],
    }


def render():
    """The generated file's text, byte for byte the same every run."""
    body = json.dumps(payload(), indent=2, sort_keys=True)
    indented = "\n".join("    " + line for line in body.splitlines())
    return f'{HEADER}(() => {{\n  "use strict";\n\n  window.DRISHTI_RESULTS_METRICS = Object.freeze(\n{indented}\n  );\n}})();\n'


def write(path=METRIC_PATH):
    """Write :func:`render` to ``path`` and return the text written."""
    target = Path(path)
    target.write_text(render(), encoding="utf-8", newline="\n")
    return target.read_text(encoding="utf-8")


def main(stream=None):
    """Regenerate the committed file and say where it was written."""
    path = METRIC_PATH
    write(path)
    print(f"wrote {path} with {len(metrics())} metrics", file=stream or sys.stdout)


if __name__ == "__main__":
    main()